from taf.cloud.cbam.catalog.catalog import Catalog


class Catalog18(Catalog):
    def __init__(self, session):
        self._session = session

    def _to_endpoint(self,
                     method,
                     url,
                     api_version=None,
                     **content):
        response = self._session.send_request(
            method=method,
            endpoint=url,
            api_version=api_version,
            **content)
        return response

    def get_info(self, api_version=None):
        response = self._to_endpoint(method='get',
                                     url='api/catalog/adapter/vnfpackages',
                                     api_version=api_version)
        data = response.data
        return data

    def post_info(self, cbam_catalog_zip, api_version=None):
        endpoint = 'api/catalog/adapter/vnfpackages'

        response = self._to_endpoint(
            method='post', url=endpoint,
            files={"content": cbam_catalog_zip},
            content_type=None,
            api_version=api_version)

        data = response.data
        return data

    def delete_info(self, vnfd_id, api_version=None):
        endpoint = 'api/catalog/adapter/vnfpackages/{}'.format(vnfd_id)

        response = self._to_endpoint(method='delete',
                                     url=endpoint,
                                     api_version=api_version)

        data = response.data
        return data
